  // contrôle : chaque fiche a autant de réglages que de variétés, dans le même ordre (début du nom)
  Textures.controleVarietes = function () {
    const out = [];
    if (typeof ROCHES === "undefined") return out;
    ROCHES.forEach((r) => {
      const l = r.varietes || [], v = Textures._VARIETES[r.id] || [];
      if (v.length !== l.length) out.push(`${r.id} : ${l.length} variétés, ${v.length} réglages`);
      v.forEach((x, i) => { if (l[i] && !l[i].nom.toLowerCase().startsWith(x.n.toLowerCase().replace(/ —$/, ""))) out.push(`${r.id}[${i}] : « ${l[i] && l[i].nom} » ≠ « ${x.n} »`); });
    });
    return out;
  };
